"""Local transmission across a smooth carrier cut and a resolved conversion layer.

Coordinates at the cut are locally orthonormal. The signed normal points into
the sleeve. The other tangent directions enter the same dot product as x.
"""
import sympy as sp


def smooth_cut():
    # Singular terms generated by a trial field jump across z = W*t.
    z, t, speed = sp.symbols("z t W", real=True)
    hbar, mass = sp.symbols("hbar m", positive=True)
    jump, slope_jump = sp.symbols("jump slope_jump")
    y = z - speed*t
    defect = (jump + slope_jump*y)*sp.Heaviside(y)
    stationary_coordinate = sp.symbols("y", real=True)
    residual = sp.I*hbar*sp.diff(defect, t) + hbar**2*sp.diff(defect, z, 2)/(2*mass)
    # Test the singular part on an arbitrary normal test function at the cut.
    residual = residual.subs(z, stationary_coordinate + speed*t).expand()
    delta = sp.DiracDelta(stationary_coordinate)
    delta_prime = sp.DiracDelta(stationary_coordinate, 1)
    a = residual.coeff(delta_prime)
    b = residual.coeff(delta)
    print("smooth cut: delta-prime =", a.subs(stationary_coordinate, 0))
    print("smooth cut: delta =", (b-sp.diff(a, stationary_coordinate)).subs(stationary_coordinate, 0))


def conversion_layer():
    t, x, z = sp.symbols("t x z")
    n, chi, ux, uz, jx, jz = [sp.Function(name)(t, x, z)
                               for name in ("n", "chi", "ux", "uz", "Jx", "Jz")]
    gamma, speed = sp.symbols("Gamma W")
    number = sp.diff(n, t) + sp.diff(n*ux, x) + sp.diff(n*uz, z)
    order = (sp.diff(n*chi, t) + sp.diff(n*chi*ux+jx, x)
             + sp.diff(n*chi*uz+jz, z) - n*gamma)
    normal_gradient, along_cut, flux_div, tangent_term, number_density, relative_speed = sp.symbols(
        "g cut_rate div_J tangential_advection n s")
    reduced = sp.expand(order-chi*number)
    reduced = reduced.subs(sp.diff(chi, t), along_cut-speed*sp.diff(chi, z))
    reduced = reduced.subs(uz, relative_speed+speed).expand()
    reduced = reduced.subs({sp.diff(chi, z): normal_gradient, ux*sp.diff(chi, x): tangent_term})
    reduced = reduced.subs(sp.diff(jx, x), flux_div-sp.diff(jz, z)).subs(n, number_density)
    slope, = sp.solve(reduced, relative_speed)
    print("order minus chi times constituent balance =", sp.expand(reduced))
    print("relative speed (nonzero g) =", sp.expand(slope))
    print("current on a regular level of chi =", sp.factor(
        (number_density*slope).subs({along_cut: 0, tangent_term: 0})))
    print("balance at g=0 =", reduced.subs(normal_gradient, 0).expand())


if __name__ == "__main__":
    smooth_cut()
    conversion_layer()
